            const fullData = await cmdRes.json();
            fullData.is_cached = false;
            fullData.observed = result.observed;
            renderEval(fullData);
        } else {
            document.getElementById('eval-content').innerHTML = 'Evaluation failed.';
        }
    } catch(e) {
        document.getElementById('eval-content').innerHTML = 'Evaluation request failed.';
    }
}

